`src/envs/dev/infra/logs.ts`
```typescript
/**
 * dev environment — application logs bucket.
 *
 * Discovery picks up every `.ts` file under `src/envs/dev/infra`, so these
 * exports land in `dist/dev/infra/manifests.yaml` alongside `main.ts`'s.
 *
 * SPEC dev: versioned + encrypted + public access blocked — all three are
 * unconditional inside `SecureBucket`, so there is nothing to pass here.
 */

import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";
const LOGS_BUCKET = "myapp-logs-dev";

// ── Application logs bucket ──────────────────────────────────────────────────

export const logs = SecureBucket({
  name: LOGS_BUCKET,
  env: ENV,
  region: REGION,
  component: "logs",
});

// ── Logs identity ────────────────────────────────────────────────────────────
// Scoped to the logs bucket only — never the assets bucket, no wildcard action
// and no wildcard resource. `s3:GetObject` comes from ReaderIam's baseline;
// `s3:PutObject` is added by enumeration.

export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: LOGS_BUCKET,
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: true,
  component: "logs-identity",
});
```

`src/envs/prod/infra/logs.ts`
```typescript
/**
 * prod environment — application logs bucket.
 *
 * Read this next to `../../dev/infra/logs.ts`. Same shape; the trust block is
 * the OIDC one this environment already uses for its assets reader, so both
 * prod identities authenticate the same way.
 */

import { ReaderIam, SecureBucket } from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const LOGS_BUCKET = "myapp-logs-prod";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

// ── Application logs bucket ──────────────────────────────────────────────────

export const logs = SecureBucket({
  name: LOGS_BUCKET,
  env: ENV,
  region: REGION,
  component: "logs",
});

// ── Logs identity ────────────────────────────────────────────────────────────
// SPEC criterion 4: least privilege, no wildcards. Scoped to the logs bucket
// only; `s3:PutObject` added by enumeration on top of the baseline reads.

export const logsReader = ReaderIam({
  name: "myapp-prod-logs",
  env: ENV,
  bucketName: LOGS_BUCKET,
  trust: {
    mode: "oidc",
    providerARN:
      "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: false,
  component: "logs-identity",
});
```

Notes:

- No file under `src/composites/` is touched, and no raw ACK resource is hand-written — both buckets come from `SecureBucket`, both identities from `ReaderIam`.
- Versioning, encryption, and the public-access block are pinned unconditionally inside `SecureBucket`, so no props for them are passed.
- Each reader's policy document is built from `bucketName: myapp-logs-{env}`, so `Resource` is `arn:aws:s3:::myapp-logs-{env}` / `.../*` — the assets bucket is not in scope, and `additionalActions` is an enumerated list with no wildcard.
- Distinct `name` values (`myapp-dev-logs` / `myapp-prod-logs`) keep the derived `-reader`, `-role`, `-sa` object names from colliding with the existing `reader` call in each environment; `component` distinguishes the labels and tags.
